// Symbolic.ts — Symbolic math wrapper for the web (nerdamer + Calculus + Algebra + Solve)
//
// Mirrors the #sym subset of Calcpad-Symbolic desktop (which uses AngouriMath in C#).
// Functions exposed to the parser:
//
//   diff(expr, var)               — derivative
//   diff2(expr, var)              — second derivative
//   pdiff(expr, var)              — partial derivative (alias of diff)
//   integrate(expr, var)          — indefinite integral
//   integrate(expr, var, a, b)    — definite integral
//   simplify(expr)                — algebraic simplification
//   expand(expr)                  — algebraic expansion
//   factor(expr)                  — factorize
//   solve(expr, var)              — solve equation = 0
//   subs(expr, var, value)        — substitute variable with value
//   sym(expr)                     — return symbolic string (no eval)
//
// All accept either strings or numbers; return strings (LaTeX-friendly when possible).

// @ts-ignore — nerdamer has no proper TS types
import nerdamer from 'nerdamer';
// @ts-ignore
import 'nerdamer/Algebra.js';
// @ts-ignore
import 'nerdamer/Calculus.js';
// @ts-ignore
import 'nerdamer/Solve.js';

const nerd: any = nerdamer;

/** Differentiate an expression w.r.t. a variable. */
export function symDiff(expr: string, variable: string): string {
  try {
    return nerd.diff(nerd(expr), variable).toString();
  } catch (err) {
    throw new Error(`diff(${expr}, ${variable}) failed: ${(err as Error).message}`);
  }
}

/** Second derivative. */
export function symDiff2(expr: string, variable: string): string {
  try {
    return nerd.diff(nerd.diff(nerd(expr), variable), variable).toString();
  } catch (err) {
    throw new Error(`diff2(${expr}, ${variable}) failed: ${(err as Error).message}`);
  }
}

/** Indefinite or definite integral. */
export function symIntegrate(expr: string, variable: string, a?: string | number, b?: string | number): string {
  try {
    if (a === undefined && b === undefined) {
      return nerd.integrate(nerd(expr), variable).toString();
    }
    const F = nerd.integrate(nerd(expr), variable);
    // Substitute upper - lower
    const Fa = F.sub(variable, String(a));
    const Fb = F.sub(variable, String(b));
    return nerd(`(${Fb.toString()}) - (${Fa.toString()})`).toString();
  } catch (err) {
    throw new Error(`integrate(${expr}, ${variable}) failed: ${(err as Error).message}`);
  }
}

/** Algebraic simplification. */
export function symSimplify(expr: string): string {
  try {
    return nerd(expr).toString();
  } catch (err) {
    throw new Error(`simplify(${expr}) failed: ${(err as Error).message}`);
  }
}

/** Algebraic expansion. */
export function symExpand(expr: string): string {
  try {
    return nerd(expr).expand().toString();
  } catch (err) {
    throw new Error(`expand(${expr}) failed: ${(err as Error).message}`);
  }
}

/** Factorize an expression. */
export function symFactor(expr: string): string {
  try {
    // nerdamer Algebra.js provides factor()
    return nerd(`factor(${expr})`).toString();
  } catch (err) {
    return symSimplify(expr); // fallback
  }
}

/** Solve equation expr = 0 for a variable. Returns string of solutions. */
export function symSolve(expr: string, variable: string): string {
  try {
    return nerd.solve(expr, variable).toString();
  } catch (err) {
    throw new Error(`solve(${expr}, ${variable}) failed: ${(err as Error).message}`);
  }
}

/** Substitute a variable with a value (numeric or symbolic). */
export function symSubs(expr: string, variable: string, value: string | number): string {
  try {
    return nerd(expr).sub(variable, String(value)).toString();
  } catch (err) {
    throw new Error(`subs(${expr}, ${variable}, ${value}) failed: ${(err as Error).message}`);
  }
}

/** Convert a symbolic string to LaTeX (for KaTeX rendering). */
export function symToLatex(expr: string): string {
  try {
    return nerd(expr).toTeX();
  } catch (err) {
    return expr;
  }
}

/** Evaluate a symbolic expression numerically (substitutes all variables). */
export function symEval(expr: string, scope: Record<string, number> = {}): number {
  try {
    let e = nerd(expr);
    for (const [k, v] of Object.entries(scope)) {
      e = e.sub(k, String(v));
    }
    return parseFloat(e.toString());
  } catch (err) {
    throw new Error(`eval(${expr}) failed: ${(err as Error).message}`);
  }
}

// ============================================================
// Laplace transforms (pattern table + nerdamer fallback)
// ============================================================

/** Laplace transform L{f(t)}(s). Supports the 15 most common cases. */
export function symLaplace(expr: string, t: string, s: string): string {
  const f = normalizeMath(expr).replace(/\s+/g, '');
  const tv = t, sv = s;

  // 1. Try nerdamer native laplace if available
  try {
    if (typeof nerd.laplace === 'function') {
      return nerd.laplace(f, tv, sv).toString();
    }
  } catch { /* fall through */ }

  // 2. Pattern table (lookup for common forms)
  // Constants
  if (/^-?\d+(\.\d+)?$/.test(f)) return `${f}/${sv}`;
  if (f === '1') return `1/${sv}`;

  // t^n
  if (f === tv) return `1/${sv}^2`;
  const tPow = new RegExp(`^${tv}\\^(\\d+)$`);
  const m1 = f.match(tPow);
  if (m1) {
    const n = parseInt(m1[1]);
    return `${factorial(n)}/${sv}^${n + 1}`;
  }

  // exp(a*t), exp(-a*t)
  const expPos = new RegExp(`^exp\\(([^()]+)\\*${tv}\\)$|^exp\\(${tv}\\*([^()]+)\\)$|^exp\\(${tv}\\)$`);
  const em = f.match(expPos);
  if (em) {
    const a = em[1] || em[2] || '1';
    return `1/(${sv}-(${a}))`;
  }
  const expNeg = new RegExp(`^exp\\(-([^()]+)\\*${tv}\\)$|^exp\\(-${tv}\\)$`);
  const em2 = f.match(expNeg);
  if (em2) {
    const a = em2[1] || '1';
    return `1/(${sv}+${a})`;
  }

  // sin(w*t), sin(t*w), sin(t) — accept any ordering
  const sinArg = matchTrigArg(f, 'sin', tv);
  if (sinArg !== null) {
    const w = sinArg || '1';
    if (w === '1') return `1/(${sv}^2+1)`;
    return `${w}/(${sv}^2+${w}^2)`;
  }
  const cosArg = matchTrigArg(f, 'cos', tv);
  if (cosArg !== null) {
    const w = cosArg || '1';
    if (w === '1') return `${sv}/(${sv}^2+1)`;
    return `${sv}/(${sv}^2+${w}^2)`;
  }
  const sinhArg = matchTrigArg(f, 'sinh', tv);
  if (sinhArg !== null) {
    const a = sinhArg || '1';
    if (a === '1') return `1/(${sv}^2-1)`;
    return `${a}/(${sv}^2-${a}^2)`;
  }
  const coshArg = matchTrigArg(f, 'cosh', tv);
  if (coshArg !== null) {
    const a = coshArg || '1';
    if (a === '1') return `${sv}/(${sv}^2-1)`;
    return `${sv}/(${sv}^2-${a}^2)`;
  }

  // exp(-a*t)*sin(w*t), exp(-a*t)*cos(w*t) — shifted
  const shiftedPre = new RegExp(`^exp\\(-([^()*]+)\\*${tv}\\)\\*(sin\\([^()]*\\)|cos\\([^()]*\\))$`).exec(f);
  if (shiftedPre) {
    const a = shiftedPre[1];
    const trigCall = shiftedPre[2];
    const fn = trigCall.startsWith('sin') ? 'sin' : 'cos';
    const w = matchTrigArg(trigCall, fn, tv);
    if (w !== null) {
      if (fn === 'sin') return `${w}/((${sv}+${a})^2+${w}^2)`;
      return `(${sv}+${a})/((${sv}+${a})^2+${w}^2)`;
    }
  }

  // t*sin(w*t) = 2*w*s / (s^2+w^2)^2
  // Use matchTrigArg to extract w from the inner sin() cleanly.
  const tSinOuter = new RegExp(`^${tv}\\*(sin\\([^()]*\\))$`).exec(f);
  if (tSinOuter) {
    const w = matchTrigArg(tSinOuter[1], 'sin', tv);
    if (w !== null) {
      const ww = w === '1' ? '1' : w;
      return `2*${ww}*${sv}/(${sv}^2+${ww}^2)^2`;
    }
  }

  // t*exp(-a*t) = 1/(s+a)^2
  const tExpMatch = new RegExp(`^${tv}\\*exp\\(-([^()]+)\\*${tv}\\)$`).exec(f);
  if (tExpMatch) {
    const a = tExpMatch[1];
    return `1/(${sv}+${a})^2`;
  }

  // Default: leave symbolic
  return `L{${expr}}(${sv})`;
}

/** Inverse Laplace transform L⁻¹{F(s)}(t). */
export function symInvLaplace(expr: string, s: string, t: string): string {
  const F = normalizeMath(expr).replace(/\s+/g, '');
  const sv = s, tv = t;

  // Try nerdamer's ilt
  try {
    if (typeof nerd.ilt === 'function') {
      return nerd.ilt(F, sv, tv).toString();
    }
  } catch { /* fall through */ }

  // Pattern table
  if (F === `1/${sv}`) return '1';
  if (new RegExp(`^1/${sv}\\^2$`).test(F)) return tv;
  const sPow = new RegExp(`^1/${sv}\\^(\\d+)$`).exec(F);
  if (sPow) {
    const n = parseInt(sPow[1]);
    return `${tv}^${n - 1}/${factorial(n - 1)}`;
  }
  const inv1 = new RegExp(`^1/\\(${sv}-([^()]+)\\)$`).exec(F);
  if (inv1) return `exp(${inv1[1]}*${tv})`;
  const inv2 = new RegExp(`^1/\\(${sv}\\+([^()]+)\\)$`).exec(F);
  if (inv2) return `exp(-${inv2[1]}*${tv})`;

  return `L⁻¹{${expr}}(${tv})`;
}

function factorial(n: number): number {
  if (n <= 1) return 1;
  let r = 1;
  for (let i = 2; i <= n; i++) r *= i;
  return r;
}

/** Match trig(W*t), trig(t*W), or trig(t) and return W as a string ('1' if bare t). */
function matchTrigArg(expr: string, fn: string, t: string): string | null {
  const re = new RegExp(`^${fn}\\(([^()]*)\\)$`);
  const m = expr.match(re);
  if (!m) return null;
  const inner = m[1];
  if (inner === t) return '1';
  // Split by * and check if t is one of the factors
  const parts = inner.split('*');
  const tIdx = parts.indexOf(t);
  if (tIdx === -1) return null;
  const rest = parts.filter((_, i) => i !== tIdx).join('*');
  return rest || '1';
}

// ============================================================
// ODEs — return the general solution form
// ============================================================

/** y' + a·y = 0  →  y = C·exp(-a·t) */
export function symOde1(a: string): string {
  return `C*exp(-(${a})*t)`;
}

/** y'' + a·y' + b·y = 0 — classify by discriminant and return general solution. */
export function symOde2(a: string, b: string): string {
  // Characteristic: λ² + a·λ + b = 0
  // Δ = a² − 4b
  const disc = `(${a})^2 - 4*(${b})`;
  try {
    const dNum = nerd(disc).toString();
    const dVal = parseFloat(dNum);
    if (!Number.isNaN(dVal)) {
      if (dVal > 1e-12) {
        // Two distinct real roots: (-a ± √Δ)/2
        const sq = nerd(`sqrt(${disc})`).toString();
        const r1 = nerd(`(-(${a}) + ${sq})/2`).toString();
        const r2 = nerd(`(-(${a}) - ${sq})/2`).toString();
        return `C1*exp(${r1}*t) + C2*exp(${r2}*t)`;
      } else if (Math.abs(dVal) < 1e-12) {
        // Repeated root: -a/2
        const r = nerd(`-(${a})/2`).toString();
        return `(C1 + C2*t)*exp(${r}*t)`;
      } else {
        // Complex conjugate: -a/2 ± i·w,  w = √(-Δ)/2
        const re = nerd(`-(${a})/2`).toString();
        const im = nerd(`sqrt(-(${disc}))/2`).toString();
        return `exp(${re}*t)*(C1*cos(${im}*t) + C2*sin(${im}*t))`;
      }
    }
  } catch { /* fall through to symbolic */ }
  // Symbolic form: roots of λ² + aλ + b = 0
  return `C1*exp(r1*t) + C2*exp(r2*t),  r1,r2 = (-(${a})±sqrt((${a})^2-4*(${b})))/2`;
}

// ============================================================
// Strain / stress / tensor operations
// ============================================================

/** 2D infinitesimal strain tensor from displacement field (u; v; x; y). */
export function symStrain2D(u: string, v: string, x: string, y: string): string {
  const exx = symDiff(u, x);
  const eyy = symDiff(v, y);
  const exy = `((${symDiff(u, y)}) + (${symDiff(v, x)}))/2`;
  return `[${exx}, ${simplifySafe(exy)}; ${simplifySafe(exy)}, ${eyy}]`;
}

/** 3D infinitesimal strain tensor (u; v; w; x; y; z). */
export function symStrain3D(u: string, v: string, w: string, x: string, y: string, z: string): string {
  const exx = symDiff(u, x);
  const eyy = symDiff(v, y);
  const ezz = symDiff(w, z);
  const exy = simplifySafe(`((${symDiff(u, y)}) + (${symDiff(v, x)}))/2`);
  const exz = simplifySafe(`((${symDiff(u, z)}) + (${symDiff(w, x)}))/2`);
  const eyz = simplifySafe(`((${symDiff(v, z)}) + (${symDiff(w, y)}))/2`);
  return `[${exx}, ${exy}, ${exz}; ${exy}, ${eyy}, ${eyz}; ${exz}, ${eyz}, ${ezz}]`;
}

/** 2D plane-stress from strains via Hooke: σ = E/(1-ν²) · [[1,ν,0],[ν,1,0],[0,0,(1-ν)/2]] · ε */
export function symStress2D(e11: string, e22: string, e12: string, E: string, nu: string): string {
  const k = `${E}/(1-(${nu})^2)`;
  const s11 = simplifySafe(`(${k})*((${e11}) + (${nu})*(${e22}))`);
  const s22 = simplifySafe(`(${k})*((${nu})*(${e11}) + (${e22}))`);
  const s12 = simplifySafe(`(${k})*(1-(${nu}))/2*2*(${e12})`);
  return `[${s11}, ${s12}; ${s12}, ${s22}]`;
}

/** Voigt notation: 2x2 tensor → [s11; s22; s12] vector (symmetric). */
export function symVoigt(s11: string, s12: string, s21: string, s22: string): string {
  const shear = simplifySafe(`((${s12}) + (${s21}))/2`);
  return `[${s11}; ${s22}; ${shear}]`;
}

/** Invariants of a 2x2 tensor: I1 = tr, I2 = det. */
export function symInvariants(a11: string, a12: string, a21: string, a22: string): string {
  const I1 = simplifySafe(`(${a11}) + (${a22})`);
  const I2 = simplifySafe(`(${a11})*(${a22}) - (${a12})*(${a21})`);
  return `I1 = ${I1}, I2 = ${I2}`;
}

/** Dyadic product a ⊗ b for 2-vectors. */
export function symDyadic(a1: string, a2: string, b1: string, b2: string): string {
  return `[${simplifySafe(`(${a1})*(${b1})`)}, ${simplifySafe(`(${a1})*(${b2})`)}; ${simplifySafe(`(${a2})*(${b1})`)}, ${simplifySafe(`(${a2})*(${b2})`)}]`;
}

function simplifySafe(expr: string): string {
  try { return nerd(expr).toString(); }
  catch { return expr; }
}

// ============================================================
// Math-friendly normalization for #sym input
// Converts Calcpad-style unicode (², ³, ·, ×, …) to nerdamer syntax.
// ============================================================
export function normalizeMath(s: string): string {
  if (!s) return s;
  // Unicode superscripts → ^n
  const supMap: Record<string, string> = {
    '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4',
    '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9',
    '⁺': '+', '⁻': '-', '⁽': '(', '⁾': ')',
  };
  let out = s;
  // Replace runs of unicode superscripts with ^(digits)
  out = out.replace(/([⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁽⁾]+)/g, (run) => {
    const asci = run.split('').map(c => supMap[c] || c).join('');
    return '^' + asci;
  });
  // Multiplication dots/crosses → *
  out = out.replace(/[·×∙⋅]/g, '*');
  // Unicode minus → -
  out = out.replace(/[−–—]/g, '-');
  // Collapse repeated ^^ (artefact of Foo²² → Foo^2^2)
  out = out.replace(/\^(\d+)\^(\d+)/g, '^$1$2');
  return out;
}

/** Install all symbolic functions in a math.js scope object. */
export function installSymbolic(scope: Record<string, unknown>): void {
  scope.diff = symDiff;
  scope.diff2 = symDiff2;
  scope.pdiff = symDiff;       // partial = diff for one variable
  scope.integrate = symIntegrate;
  scope.simplify = symSimplify;
  scope.expand = symExpand;
  scope.factor = symFactor;
  scope.solve_sym = symSolve;
  scope.subs = symSubs;
  scope.sym = (e: string) => e;  // identity (just keep as string)
  scope.tex = symToLatex;
  // Advanced symbolic
  scope.laplace = symLaplace;
  scope.ilaplace = symInvLaplace;
  scope.ode1 = symOde1;
  scope.ode2 = symOde2;
  scope.strain = (...args: string[]) => args.length === 4
    ? symStrain2D(args[0], args[1], args[2], args[3])
    : symStrain3D(args[0], args[1], args[2], args[3], args[4], args[5]);
  scope.stress = symStress2D;
  scope.voigt = symVoigt;
  scope.invariants = symInvariants;
  scope.dyadic = symDyadic;
}
